import unittest

from solucao import somar_lista


class TestPercorrerUmaLista(unittest.TestCase):
    def test_soma_tres_numeros(self):
        """somar_lista devolve a soma dos itens"""
        self.assertTrue(somar_lista([1, 4, 2]) == 7)

    def test_soma_um_numero(self):
        """somar_lista de um item devolve o proprio item"""
        self.assertTrue(somar_lista([5]) == 5)

    def test_lista_vazia_soma_zero(self):
        """somar_lista da lista vazia devolve 0"""
        self.assertTrue(somar_lista([]) == 0)

